CREATE TABLE result AS SELECT t1.x,t2.x+1,t3.x+2,t4.x+3,t5.x+4,t6.x+5,t7.x+6,t8.x+7,t9.x+8,t10.x+9,t11.x+10,t12.x+11,t13.x+12,t14.x+13,t15.x+14 FROM t AS t1,t AS t2,t AS t3,t AS t4,t AS t5,t AS t6,t AS t7,t AS t8,t AS t9,t AS t10,t AS t11,t AS t12,t AS t13,t AS t14,t AS t15 WHERE t2.x=t1.x AND t3.x=t2.x AND t4.x=t3.x AND t5.x=t4.x AND t6.x=t5.x AND t7.x=t6.x AND t8.x=t7.x AND t9.x=t8.x AND t10.x=t9.x AND t11.x=t10.x AND t12.x=t11.x AND t13.x=t12.x AND t14.x=t13.x AND t15.x=t14.x;